ltest = [{"n":i+1,"question_zh":f"（听录音，选一个）{a[0]} {a[1]} {a[2]}","image":img(a[4]),"script_zh":f"{a[0]}  {a[1]}  {a[2]}","options":["A","B","C"],"optionTexts":[a[0][2:],a[1][2:],a[2][2:]],"answer":a[3],"explanation_mn":a[5]} for i,a in enumerate(LISTEN_SCRIPT)]

def _mk(n,q,opts,ans,expl,seed,extra=None):
    o,_=shuffle(opts,ans,seed); d={"n":n,"question_zh":q,"options":o,"answer":ans,"explanation_mn":expl}
    if extra: d.update(extra)
    return d
def RD(n,q,opts,ans,expl,seed): return _mk(n,q,opts,ans,expl,seed)
def SO(n,words,ans,dis,expl,seed): return _mk(n,"（把词连成句子）"+words,[ans]+dis,ans,expl,seed)
def MC(n,q,ans,expl,seed):
    bank=["聪明极了","好吃极了","冷极了","漂亮极了","难极了"]
    return _mk(n,q+" ↔ ?",bank,ans,expl,seed)
def NM(n,q,ans,dis,expl,seed): return _mk(n,q,[ans]+dis,ans,expl,seed)

